        return True, present


    present_e, value_e = resolve(expected_result, pointer)
    present_a, value_a = resolve(result_raw, pointer)
    verdict = {
        "status": "mismatched",
        "path": pointer,
        "expectedPresent": present_e,
        "actualPresent": present_a,
    }
    if present_e:
        verdict["expected"] = value_e
    if present_a:
        verdict["actual"] = value_a
    return verdict


def _unescape_token(raw_token: str) -> str:
    """Reverse RFC 6901 reference-token escaping (``~1`` then ``~0``)."""
    return raw_token.replace("~1", "/").replace("~0", "~")

